import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

import '../models.dart';
import 'camera_contract.dart';

abstract class CameraService {
  String get name;
  bool get isSimulated;
  Future<void> connect();

  /// Disconnects the camera. Default is a no-op for mock/unavailable services.
  Future<void> disconnect() async {}

  /// Releases adapter resources on app shutdown. Default no-op.
  Future<void> dispose() async {}

  /// [captureId] is generated by the capture coordinator. Native adapters may
  /// use it to correlate shutter/transfer events. Implementations must only
  /// return after a valid image has been received.
  Future<CapturedImage> capture({String? captureId});
}

/// Optional capability implemented by physical camera adapters. Mock/unavailable
/// services intentionally do not implement it.
abstract class CameraLiveViewSource {
  Stream<Uint8List> get liveViewFrames;
  Future<void> startLiveView();
  Future<void> stopLiveView();
}

/// Optional native event source used to surface connection-loss state.
abstract class CameraEventSource {
  Stream<CameraAdapterEvent> get parsedEvents;
}

class MockCameraService implements CameraService {
  const MockCameraService();
  static int _counter = 0;

  @override
  String get name => 'Mock Camera';

  @override
  bool get isSimulated => true;

  @override
  Future<void> connect() async {}

  @override
  Future<void> disconnect() async {}

  @override
  Future<void> dispose() async {}

  @override
  Future<CapturedImage> capture({String? captureId}) async {
    final captureNumber = _counter + 1;
    _counter = captureNumber;
    const width = 1200;
    const height = 1800;
    final recorder = ui.PictureRecorder();
    final canvas = ui.Canvas(recorder);
    final rect = Rect.fromLTWH(0, 0, width.toDouble(), height.toDouble());
    final paint = ui.Paint()
      ..shader = ui.Gradient.linear(
        const Offset(0, 0),
        Offset(width.toDouble(), height.toDouble()),
        [
          const [
            Color(0xFFCE346B),
            Color(0xFF1F6F8B),
            Color(0xFFB4542A),
            Color(0xFF4E7A3A),
          ][captureNumber % 4],
          const Color(0xFF2A2438),
        ],
      );
    canvas.drawRect(rect, paint);
    final text = TextPainter(
      text: TextSpan(
        text: 'SIMULATED\nCAMERA\n\nNO EOS 60D\n\nCAPTURE #$captureNumber',
        style: TextStyle(
          color: Colors.white,
          fontSize: 86,
          fontWeight: FontWeight.w800,
          height: 1.25,
        ),
      ),
      textDirection: TextDirection.ltr,
      textAlign: TextAlign.center,
    )..layout(maxWidth: width.toDouble());
    text.paint(
      canvas,
      Offset((width - text.width) / 2, (height - text.height) / 2),
    );
    final image = await recorder.endRecording().toImage(width, height);
    final data = await image.toByteData(format: ui.ImageByteFormat.png);
    image.dispose();
    if (data == null) throw StateError('Could not encode mock image');
    final id =
        captureId ?? 'mock_${DateTime.now().microsecondsSinceEpoch}_$_counter';
    return CapturedImage(
      id: id,
      bytes: data.buffer.asUint8List(),
      width: width,
      height: height,
      capturedAt: DateTime.now(),
      captureId: id,
    );
  }
}

class UnavailableCameraService implements CameraService {
  final String reason;
  const UnavailableCameraService(this.reason);

  @override
  String get name => 'Camera unavailable';

  @override
  bool get isSimulated => false;

  @override
  Future<void> connect() async {
    throw StateError(reason);
  }

  @override
  Future<void> disconnect() async {}

  @override
  Future<void> dispose() async {}

  @override
  Future<CapturedImage> capture({String? captureId}) async {
    throw StateError(reason);
  }
}
